window.ScripturaLexicons.BDAG_PART_0219 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-01\" data-source=\"BDAG\" data-search=\"λίθινος, ίνη, ον adjetivo feito de pedra; pétreo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λίθινος, ίνη, ον</td><td>adjetivo</td><td>feito de pedra; pétreo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-02\" data-source=\"BDAG\" data-search=\"λιθοβολέω verbo atirar pedras; apedrejar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λιθοβολέω</td><td>verbo</td><td>atirar pedras; apedrejar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-03\" data-source=\"BDAG\" data-search=\"λιθοξόος, ου, ὁ substantivo masculino escultor; entalhador de pedra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λιθοξόος, ου, ὁ</td><td>substantivo masculino</td><td>escultor; entalhador de pedra</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-04\" data-source=\"BDAG\" data-search=\"λίθος, ου, ὁ substantivo masculino pedra; gema; pedra simbólica BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λίθος, ου, ὁ</td><td>substantivo masculino</td><td>pedra; gema; pedra simbólica</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-05\" data-source=\"BDAG\" data-search=\"λιθόστρωτος, ον adjetivo; substantivo neutro pavimentado de pedra; pavimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λιθόστρωτος, ον</td><td>adjetivo; substantivo neutro</td><td>pavimentado de pedra; pavimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-06\" data-source=\"BDAG\" data-search=\"λικμάω verbo joeirar; esmagar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λικμάω</td><td>verbo</td><td>joeirar; esmagar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-07\" data-source=\"BDAG\" data-search=\"λιμά, remissão veja λαμά e λεμά BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λιμά,</td><td>remissão</td><td>veja λαμά e λεμά</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-08\" data-source=\"BDAG\" data-search=\"λιμήν, ένος, ὁ substantivo masculino porto; abrigo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λιμήν, ένος, ὁ</td><td>substantivo masculino</td><td>porto; abrigo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-09\" data-source=\"BDAG\" data-search=\"λίμμα remissão veja λεῖμμα BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λίμμα</td><td>remissão</td><td>veja λεῖμμα</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-10\" data-source=\"BDAG\" data-search=\"λίμνη, ης, ἡ substantivo feminino lago; tanque; lago apocalíptico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λίμνη, ης, ἡ</td><td>substantivo feminino</td><td>lago; tanque; lago apocalíptico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-11\" data-source=\"BDAG\" data-search=\"λιμός, οῦ, ὁ substantivo masculino fome; carestia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λιμός, οῦ, ὁ</td><td>substantivo masculino</td><td>fome; carestia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-12\" data-source=\"BDAG\" data-search=\"λινοκαλάμη, ης, ἡ substantivo feminino caule de linho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λινοκαλάμη, ης, ἡ</td><td>substantivo feminino</td><td>caule de linho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-13\" data-source=\"BDAG\" data-search=\"λίνον, ου, τό substantivo neutro linho; pavio; tecido; rede de pesca BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λίνον, ου, τό</td><td>substantivo neutro</td><td>linho; pavio; tecido; rede de pesca</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-14\" data-source=\"BDAG\" data-search=\"Λίνος, ου, ὁ nome próprio masculino Lino, cristão do Novo Testamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λίνος, ου, ὁ</td><td>nome próprio masculino</td><td>Lino, cristão do Novo Testamento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-15\" data-source=\"BDAG\" data-search=\"λινοῦς, ῆ, οῦν adjetivo feito de linho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λινοῦς, ῆ, οῦν</td><td>adjetivo</td><td>feito de linho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-16\" data-source=\"BDAG\" data-search=\"λιπαίνω verbo ungir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λιπαίνω</td><td>verbo</td><td>ungir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-17\" data-source=\"BDAG\" data-search=\"λιπαρός, ά, όν adjetivo luxuoso; rico; resplandecente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λιπαρός, ά, όν</td><td>adjetivo</td><td>luxuoso; rico; resplandecente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-18\" data-source=\"BDAG\" data-search=\"λιποτακτέω remissão veja λειποτακτέω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λιποτακτέω</td><td>remissão</td><td>veja λειποτακτέω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-19\" data-source=\"BDAG\" data-search=\"λιτανεύω verbo suplicar; rogar; orar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λιτανεύω</td><td>verbo</td><td>suplicar; rogar; orar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0219-20\" data-source=\"BDAG\" data-search=\"λίτρα, ας, ἡ substantivo feminino libra romana; unidade de peso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λίτρα, ας, ἡ</td><td>substantivo feminino</td><td>libra romana; unidade de peso</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0219-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίθινος, ίνη, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λίθινος</span>, <span class=\"greek\">ίνη</span>, <span class=\"greek\">ον</span> (Pind., Hdt.+; ins, pap, LXX; En 99:7 [cj.]; TestSol 11:8 C; Jos., Ant. 14, 57; 15, 401; Just., D. 9, 3) (feito de) pedra. <span class=\"greek\">εἴδωλα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:20</a>; <span class=\"greek\">θεοί</span> AcPl Ha 1, 19; cf. Dg 2:7 (veja Da 5:4, 23 Theod.; Hermocles [IV/III a.C.] p. 174, 19 Coll. Alex. [=Athen. 6, 63, 253e] em contraste com um <span class=\"greek\">ξύλινος</span> ou <span class=\"greek\">λίθινος</span> <span class=\"greek\">θεός</span>, Demétrio Poliorcetes é um <span class=\"greek\">ἀληθινός</span>.—Diod S 22, 9, 4 <span class=\"greek\">ἀγάλματα</span> [= <span class=\"greek\">θεοί</span>] <span class=\"greek\">λίθινα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ξύλινα</span>). <span class=\"greek\">ὑδρίαι</span> talhas para água <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:6</a> (Athen. 13 p. 589 B <span class=\"greek\">ὑδρία</span> <span class=\"greek\">λιθίνη</span>; cf. POxy 937, 13 <span class=\"greek\">τῆς</span> <span class=\"greek\">φιάλης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λιθίνης</span>). Quanto às tábuas da Lei <span class=\"greek\">πλάκες</span> <span class=\"greek\">λ</span>. (LXX) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:3</a>; B 4:7 (Ex 31:18).—Figuradamente (Herodas 7, 109; Dio Chrys. 71 [21], 13; Ps.-Aeschin., Ep. 10, 10; Alciphron 4, 16, 7; Libanius, Or. 25, 47 vol. II 559, 12f.; Philo, Mos. 2, 202 <span class=\"greek\">λ</span>. <span class=\"greek\">ψυχή</span>) quanto ao coração <span class=\"greek\">καρδία</span> <span class=\"greek\">λ</span>. um coração de pedra, isto é, insensível B 6:14 (Ezk 11:19; 36:26).—DELG s.v. <span class=\"greek\">λίθος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθοβολέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λιθοβολέω</span> (veja <span class=\"greek\">λίθος</span>, <span class=\"greek\">βάλλω</span>) imperfeito <span class=\"greek\">ἐλιθοβόλουν</span>; futuro plural <span class=\"greek\">λιθοβολήσουσιν</span> LXX; 1º aoristo <span class=\"greek\">ἐλιθοβόλησα</span>. Na voz passiva: 1º futuro <span class=\"greek\">λιθοβοληθήσομαι</span>; perfeito, 3ª pessoa do singular <span class=\"greek\">λελιθοβόληται</span> 3 Km 20:14.</p><p class=\"entry-text\">① atirar pedras contra alguém (Diod S 13, 10, 6; 17, 41, 8; Plut., Mor. 1011e) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:4</a> variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:5</a> (sobre o acusativo que indica o alvo, contra alguém ou algo cf. Ps.-Demetr. c. 115).</p><p class=\"entry-text\">② apedrejar (até a morte) (LXX) <span class=\"greek\">τινά</span>, alguém; os mensageiros de Deus (ParJer 9:22; 28:30) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:34</a>. Estêvão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.58\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:58f</a>. (Arrian, Anab. 4, 14, 3: os conspiradores contra Alexandre são apedrejados pelos presentes após o julgamento [<span class=\"greek\">πρὸς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">παρόντων</span>]). Na voz passiva (Aristodemus [II a.C.]: 383 Fgm. 6 Jac.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:5</a> variante textual (em lugar de <span class=\"greek\">λιθάζειν</span>). Um animal <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:20</a> (cf. Ex 19:13).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθοξόος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λιθοξόος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">λίθος</span> + <span class=\"greek\">ξέω</span> «talhar»; Timon Fgm. 25 D. [em Diog. L. 2, 19]) escultor (assim em Plut., Mor. 74d; Ptolem., Apotel. 4, 4, 5; IG III, 1372) Dg 2:3.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίθος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λίθος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom.+; na literatura aqui considerada, sempre masculino)</p><p class=\"entry-text\">① pedra, em geral: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:9</a> (ZNW 9, 1908, 77f; 341f); 4:3, 6 (Ps 90:12); 7:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:8</a>; 4:3, 11 (Ps 90:12); 11:11 variante textual; 19:40 (cf. 4 Esdr 5:5 e as pedras que «ouvem» (<span class=\"greek\">πέτραι</span>) PGM 36, 263); 22:41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:7</a>, 59; 10:31; Ox 1 recto, 6 (ASyn. 171, 5)=GTh 77 (veja AWalls, VigChr 16, ’62, 71–78; cf. Lucian, Hermotim. 81 p. 826 <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐρανῷ</span> <span class=\"greek\">ἐστιν</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">πεφοίτηκεν</span>, <span class=\"greek\">οἷον</span> <span class=\"greek\">ξύλων</span> <span class=\"greek\">κ</span>. <span class=\"greek\">λίθων</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ζῴων</span>). Quanto ao sangue (mas <span class=\"greek\">πτῶμα</span> em papiros) de Zacarias, que se transformou em pedra GJs 24:3.</p><p class=\"entry-text\">② pedra, de um tipo específico</p><p class=\"entry-text\">ⓐ de pedras utilizadas na construção (Dio Chrys. 57 [74], 26; Enômao em Eus., PE 5, 24, 4 <span class=\"greek\">λίθοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ξύλοι</span>; Palaeph. p. 62, 7; PPetr II, 13 [18a], 7 [258 a.C.]; Dt 27:5f; 3 Km 6:7; TestSol 2:5 e outros; JosAs 2:17) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:1f</a> (LGaston, No Stone on Another, ’70 [queda de Jerusalém]); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:44</a>; 21:6 (<span class=\"greek\">λίθος</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">λίθῳ</span>, como em Aristipo Fgm. 20 FPhGr [em Diog. L. 2, 72]); Hv 3, 2, 4–9; 3, 4, 2f; 3, 5, 1–3; 3, 6, 3; 6f; 3, 7, 1; 5; Hs 9, 3, 3ff e outros; <span class=\"greek\">λ</span>. <span class=\"greek\">καλοί</span> pedras valiosas (provavelmente tipos de mármore; cf. Diod S 1, 66, 3 <span class=\"greek\">κάλλιστοι</span> <span class=\"greek\">λίθοι</span>; Jos., Ant. 15, 392) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:5</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:12</a> também é classificado aqui por Blass e Dssm., Pls2 1925, 245f (Paul, 1926, 212ff); veja b abaixo.</p><p class=\"entry-text\">ⓑ de pedras preciosas, joias (TestSol 1:3 e outros; TestAbr, JosAs, Joseph.; Ant. 17, 197; Synes., Ep. 3 p. 158b) <span class=\"greek\">λίθος</span> <span class=\"greek\">καθαρός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:6</a> variante textual. Principalmente na combinação <span class=\"greek\">λίθος</span> <span class=\"greek\">τίμιος</span> (<span class=\"greek\">τιμιώτατος</span>) e mencionado ao lado de ouro, prata ou mesmo pérolas (Appian, Liby. 66 §297; Herodian 5, 2, 4; Da 11:38 Theod.; 2 Km 12:30; TestSol 1:6; TestAbr A 6 p. 83, 23 [Stone p. 14]; JosAs 2:3; 18:4; cf. TestAbr A 3 p. 80, 12 [Stone p. 8] <span class=\"greek\">πολύτιμοι</span>; TestJob 28:5 <span class=\"greek\">πολυτελεῖς</span>, <span class=\"greek\">ἔνδοξοι</span>; JosAs 2:7 e outros <span class=\"greek\">πολυτελεῖς</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:4</a>; 18:12, 16; 21:11, 19 (veja a bibliografia no verbete <span class=\"greek\">ἀμέθυστος</span>. Também FCumont3 246, 87). Igualmente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:12</a>, o modo como a palavra é empregada dificilmente admite outro significado; por isso, deve-se supor (a menos que seja suficiente imaginar a construção adornada com pedras preciosas [Diod S 3, 47, 6f: o uso de ouro, prata e pedras preciosas na construção de palácios entre os sabeus; Lucian, Imag. 11 <span class=\"greek\">ὁ</span> <span class=\"greek\">νεὼς</span> <span class=\"greek\">λίθοις</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πολυτελέσιν</span> <span class=\"greek\">ἠσκημένος</span> <span class=\"greek\">κ</span>. <span class=\"greek\">χρυσῷ</span>]) que Paulo tinha em mente edifícios imaginários (Ps.-Callisth. 3, 28, 4: na cidade de Hélio, junto ao mar Vermelho, existem 12 <span class=\"greek\">πύργοι</span> <span class=\"greek\">χρυσῷ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σμαράγδῳ</span> <span class=\"greek\">ᾠκοδομημένοι</span>· <span class=\"greek\">τὸ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τεῖχος</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">λίθου</span> <span class=\"greek\">Ἰνδικοῦ</span> <span class=\"greek\">κτλ</span>.) como em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:18ff</a>; Is 54:11f; Tob 13:17, ou simplesmente mencionou os materiais mais caros, sem considerar se eles poderiam de fato ser usados para erguer um edifício (em Fênix de Colofão [III a.C.] 1, 9: AnthLG I/33 ’54 Diehl o rico esnobe imagina casas <span class=\"greek\">ἐγ</span> [=<span class=\"greek\">ἐκ</span>] <span class=\"greek\">λίθου</span> <span class=\"greek\">σμαραγδίτου</span>. Veja <span class=\"greek\">χρυσίον</span>.—Veja a acima).—<span class=\"greek\">λ</span>. <span class=\"greek\">ἴασπις</span> (veja esse verbete) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:3</a>.</p><p class=\"entry-text\">ⓒ de pedras de moinho <span class=\"greek\">λ</span>. <span class=\"greek\">μυλικός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:2</a>. Duas vezes como variante textual de <span class=\"greek\">μύλος</span> <span class=\"greek\">ὀνικός</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:42</a>. Variante textual <span class=\"greek\">λ</span>. <span class=\"greek\">ὡς</span> <span class=\"greek\">μύλινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:21</a>.</p><p class=\"entry-text\">ⓓ de grandes pedras usadas para fechar sepulturas (Chariton 3, 3, 1 <span class=\"greek\">παραγενόμενος</span> <span class=\"greek\">εὗρε</span> <span class=\"greek\">τ</span>. <span class=\"greek\">λίθους</span> <span class=\"greek\">κεκινημένους</span> <span class=\"greek\">κ</span>. <span class=\"greek\">φανερὰν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">εἴσοδον</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.60\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:60</a>, 66; 28:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:46</a>; 16:3f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:38f</a>, 41; 20:1; GPt 8:32 e outros. Também quanto às tábuas da lei mosaica <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:7</a>.</p><p class=\"entry-text\">ⓔ de imagens pétreas dos deuses (Dt 4:28; Ezk 20:32; Just., D. 113, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:29</a>; 2 Cl 1:6; cf. PtK 2 p. 14, 14; Dg 2:2.</p><p class=\"entry-text\">ⓕ em imagens relacionadas ao povo de Deus e ao transcendente (nas passagens de Hv 3 e Hs 9 mencionadas em 2a acima, a torre e suas pedras são simbólicas): quanto a Cristo (cf. Just., D. 86, 3) <span class=\"greek\">λ</span>. <span class=\"greek\">ζῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:4</a>. Igualmente, quanto aos cristãos <span class=\"greek\">λίθοι</span> <span class=\"greek\">ζῶντες</span> pedras vivas (no templo espiritual) vs. 5 (JPlumpe, Vivum saxum, vivi lapides: Traditio 1, ’43, 1–14). <span class=\"greek\">ὡς</span> <span class=\"greek\">ὄντες</span> <span class=\"greek\">λίθοι</span> <span class=\"greek\">ναοῦ</span> <span class=\"greek\">πατρός</span> como pedras da construção do templo do Pai IEph 9:1. 1 Pt e B 6:2c, 3 (veja LBarnard, Studia Evangelica, ed. FCross, ’64, III, 306–13: NT e B) também se referem a Cristo como a <span class=\"greek\">λ</span>. <span class=\"greek\">ἐκλεκτὸς</span> <span class=\"greek\">ἀκρογωνιαῖος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:6</a> (cf. Is 28:16; ESiegman, CBQ 18, ’56, 364–79; JElliott, The Elect and the Holy ’66, especialmente 16–38; veja <span class=\"greek\">ἀκρογωνιαῖος</span>), a <span class=\"greek\">λ</span>., <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ἀπεδοκίμασαν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">οἰκοδομοῦντες</span> vs. 7 (Ps 117:22)—igualmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:17</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:20</a> variante textual (quanto à bibliografia, veja <span class=\"greek\">κεφαλή</span> 2b)—e, por fim, a <span class=\"greek\">λ</span>. <span class=\"greek\">προσκόμματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:8</a> (Is 8:14)—igualmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:32f</a>. A influência da mesma passagem do Antigo Testamento (Is 8:14f) também se percebe em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:18</a> (Daimachus [IV a.C.]: 65 Fgm. 8 Jac. fala, em sua obra <span class=\"greek\">περὶ</span> <span class=\"greek\">εὐσεβείας</span>, da queda de uma pedra sagrada do céu <span class=\"greek\">πεσεῖν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λίθον</span>).—SKottek, Names, Roots and Stones in Jewish Lore: Proceedings XXXII Intern. Congr. of History of Medicine, Antwerp n.d. [’91] 63–74; também do mesmo autor: ANRW II/37/3 p. 2855 n. 53 sobre o uso de pedras na Antiguidade. B. 51; 442. DELG. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθόστρωτος, ον</h1><div class=\"entry-meta\"><span>adjetivo; substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λιθόστρωτος</span>, <span class=\"greek\">ον</span> (veja <span class=\"greek\">λίθος</span>, <span class=\"greek\">στρώννυμι</span>; Soph. et al.; Epict. 4, 7, 37 variante textual; POxy 2138, 15; PFlor 50, 97 [268 d.C.] <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λιθοστρώτου</span> <span class=\"greek\">δρόμου</span> <span class=\"greek\">Ἕρμου</span>; 2 Ch 7:3; Esth 1:6; SSol 3:10; EpArist 88; Jos., Bell. 6, 85; 189) «pavimentado com blocos de pedra», também como substantivo <span class=\"greek\">τὸ</span> <span class=\"greek\">λιθόστρωτον</span> (IG IV2/1, 110, 19 [IV/III a.C.]; <span class=\"greek\">Κυπρ</span>. I p. 58 no. 1 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἡραίου</span> <span class=\"greek\">ἕως</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λιθοστρώτου</span>; 2 Ch 7:3) pavimento de pedra ou mosaico. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:13</a>, tanto «pavimento» quanto «mosaico» são possíveis; o lugar mencionado é o chamado «em hebraico, Gabatá» (veja <span class=\"greek\">Γαβ</span>.), onde Pilatos proferiu a sentença contra Jesus.—REngelmann, BPhW 27, 1907, 341; 1652ff; Vincent-Abel, Jérusalem II 1926, 570; LVincent, RB 42, ’33, 83–113; 46, ’37, 563–70; 59, ’50, 513–30; ECerny, CBQ 4, ’42, 159f; PBenoit, RB 59, ’50, 531–50.—DELG s.v. <span class=\"greek\">στόρνυμι</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λικμάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λικμάω</span> futuro <span class=\"greek\">λικμήσω</span>; aoristo <span class=\"greek\">ἐλίκμησα</span> LXX. Na voz passiva: particípio aoristo neutro <span class=\"greek\">λικμηθέντες</span> Wsd 11:20; particípio perfeito neutro <span class=\"greek\">λελικμημένα</span> Is 30:24 (no sentido de «joeirar» Hom. e outros; PSI 522, 2 [248/247 a.C.]; BGU 1040, 11; LXX; Philo, De Jos. 112; Jos., Ant. 5, 328); na literatura aqui considerada, somente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:44</a>=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:18</a> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">ἂν</span> <span class=\"greek\">πέσῃ</span> (isto é, <span class=\"greek\">ὁ</span> <span class=\"greek\">λίθος</span>, veja esse verbete, ao final), <span class=\"greek\">λικμήσει</span> <span class=\"greek\">αὐτόν</span>, passagem em que as versões siríacas sinaítica e curetoniana, e a Vulgata, entendem «esmagar» (quanto a esse significado, cf. escólio a Nicander, Ther. 114 [ao lado de <span class=\"greek\">τοὺς</span> <span class=\"greek\">στάχυας</span> <span class=\"greek\">τρίβω</span>]; Da 2:44 Theod. e BGU 146, 8, o último documento apresenta queixa contra aqueles que <span class=\"greek\">ἐλίκμησάν</span> <span class=\"greek\">μου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">λάχανον</span> «pisaram, destruíram minhas hortaliças» [Dssm., NB 52f; BS 225f], e veja Boll. 130, 1).—DELG. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιμά,</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λιμά</span>, veja <span class=\"greek\">λαμά</span>, <span class=\"greek\">λεμά</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιμήν, ένος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λιμήν</span>, <span class=\"greek\">ένος</span>, <span class=\"greek\">ὁ</span> (Homero e outros; ins, pap, LXX; EpArist 115; Philo; Jos., Ant. 17, 87 al.; empréstimo na literatura rabínica, mas, a esse respeito, veja MLubetski, JQR 69, ’79, 158–80) porto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:12a</a>; <span class=\"greek\">λιμὴν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κρήτης</span> um porto para Creta (=«um porto para navegar de Creta e para Creta» Warnecke, Romfahrt 28f) b; AcPl Ha 5, 15 (?); 7, 37. Figuradamente (Trag.+; <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> p. 15, 6 V.; Herm. Wr. 7, 1b; Philo, Decal. 67 e frequentemente) <span class=\"greek\">λιμένος</span> <span class=\"greek\">τυγχάνειν</span> alcançar o porto ISm 11:3. O marinheiro açoitado pela tempestade anseia por ele IPol 2:3.—Como topônimo: <span class=\"greek\">Καλοὶ</span> <span class=\"greek\">λιμένες</span> (veja o verbete autônomo). Sobre o plural, cf. Jos., Ant. 13, 261; 14, 76) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:8</a>.—B. 738. DELG s.v. <span class=\"greek\">λειμών</span> B. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίμμα</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λίμμα</span> veja <span class=\"greek\">λεῖμμα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίμνη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λίμνη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Homero e outros; ins, pap, LXX; GrBar; ApocMos 37; Philo, Aet. M. 147; 148; Jos., Ant. 5, 81) massa de água menor que, por exemplo, o mar Mediterrâneo, mas não limitada ao que normalmente se denomina lago.</p><p class=\"entry-text\">① massa de água continental como fenômeno natural, de tamanho variável entre lago e tanque</p><p class=\"entry-text\">ⓐ lago, quanto ao lago de Genesaré (exceto em Lucas, geralmente denominado <span class=\"greek\">θάλασσα</span>; veja aquele verbete, acepção 2, e cf. <span class=\"hebrew\" dir=\"rtl\">יָם</span>) <span class=\"greek\">ἡ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">Γεννησαρέτ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:1</a>. O emprego absoluto de <span class=\"greek\">ἡ</span> <span class=\"greek\">λ</span>. também possui esse sentido (Jos., Vi. 96; 165; 304, Ant. 14, 450) vs. 2; 8:22f, 33.</p><p class=\"entry-text\">ⓑ tanque <span class=\"greek\">ἡ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Δαυίδ</span> o tanque de Davi, segundo Ox 840, 25, uma bacia no recinto do templo empregada pelos sacerdotes para banhos (ZNW 9, 1908, 6f; 15, 1914, 338; Unknown Sayings 36–49).</p><p class=\"entry-text\">② fenômeno transcendente semelhante a um lago, lago (em cenário apocalíptico)</p><p class=\"entry-text\">ⓐ lago de fogo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:14ab</a>, 15 (cf. JosAs 12:10 <span class=\"greek\">ἄβυσσος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πυρός</span>) ou de fogo e enxofre vs. 10; cf. 19:20; 21:8, no qual os inimigos de Deus são castigados. ApcPt 8:23 pecadores são castigados em uma <span class=\"greek\">λίμνη</span> <span class=\"greek\">μεγάλη</span> <span class=\"greek\">πεπληρωμένη</span> <span class=\"greek\">βορβόρου</span> <span class=\"greek\">φλεγομένου</span>. Quanto a 11:26, veja <span class=\"greek\">ἰχώρ</span>. <span class=\"greek\">λ</span>. <span class=\"greek\">μεγάλη</span> <span class=\"greek\">πεπληρωμένῃ</span> <span class=\"greek\">πύρου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">αἱματος</span> 16:31.</p><p class=\"entry-text\">ⓑ lago da salvação <span class=\"greek\">βάπτισμα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σωτηρίᾳ</span> <span class=\"greek\">Ἀχερουσίας</span> <span class=\"greek\">λίμνης</span>, <span class=\"greek\">ἣν</span> <span class=\"greek\">καλοῦσιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἠλυσίῳ</span> <span class=\"greek\">πεδίῳ</span> na purificação pelas (águas) salvíficas do lago Aquerúsio, como chamam esse lugar (supostamente situado) nos Campos Elísios ApcPt Rainer 4–6 (ApcMos 37; cf. GrBar 10:2ff).—B. 38. DELG s.v. <span class=\"greek\">λειμών</span> C. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λιμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> e <span class=\"greek\">ἡ</span> (quanto ao feminino, veja <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:25</a>, variante textual; 15:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:28</a>; B-D-F §2 ao final; 49, 1; Mlt-H. 123f; W-S §8, 10; Phryn. 188 Lob.; Ael. Dion. <span class=\"greek\">λ</span>, 16; Thumb 67.—A palavra ocorre desde Homero; UPZ 11, 27 e 19, 21 <span class=\"greek\">τῷ</span> <span class=\"greek\">λ</span>.; 42, 9 <span class=\"greek\">τῆς</span> <span class=\"greek\">λ</span>.; PSI 399, 10 [III a.C.] <span class=\"greek\">τῇ</span> <span class=\"greek\">λ</span>.; LXX [Thackeray 146]; TestSol 18:8 H; Test12Patr; JosAs; 4 [6] Esdr [POxy 1010, 13 e 19]; Ath., R. 4 p. 52, 19; 21 p. 75, 2).</p><p class=\"entry-text\">① fome <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:35</a>. <span class=\"greek\">λιμῷ</span> <span class=\"greek\">ἀπόλλυμαι</span> estou morrendo de fome, isto é, prestes a morrer de inanição (Ael. Aristid. 46 p. 271 D.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:17</a>; (com <span class=\"greek\">δίψος</span>; cf. Aeschyl., Pers. 483; X., Mem. 1, 4, 13; Is 5:13; TestJos 1:5; Jos., Bell. 3, 189) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:27</a>.</p><p class=\"entry-text\">② fome coletiva, carestia (escólio a Aristófanes, Plut. 31 <span class=\"greek\">λιμοῦ</span> <span class=\"greek\">γενομένου</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">Ἀττικῇ</span>; Gen 12:10; JosAs; Philo, Rer. Div. Her. 287) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:25</a> (4 Km 6:25 <span class=\"greek\">ἐγέν</span>. <span class=\"greek\">λ</span>. <span class=\"greek\">μέγας</span>); 15:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:11</a> (cf. Gen 41:54); 11:28 (Jos., Ant. 3, 320; 20, 101 <span class=\"greek\">μέγας</span> <span class=\"greek\">λ</span>.—KGapp, The Universal Famine under Claudius: HTR 28, ’35, 258–65; RFunk, JBL 75, ’56, 130–36; Haenchen, sobre Atos 11:29f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:8</a>; 18:8. <span class=\"greek\">ἐν</span> <span class=\"greek\">λιμῷ</span> em tempo de fome 1 Cl 56:9 (Job 5:20; 4 [6] Esdr [POxy 1010, 13f] <span class=\"greek\">ἐν</span> <span class=\"greek\">λειμῷ</span> <span class=\"greek\">διαφθαρήσονται</span>). <span class=\"greek\">λιμοί</span> fomes coletivas entre as tribulações dos últimos dias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:11</a>; na última passagem e na variante textual de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:7</a>, <span class=\"greek\">λοιμοί</span> («pragas, pestilências») aparece associado a elas (quanto a essa associação, cf. Hes., Op. 243; Hdt. 7, 171; Thu. 2, 54, 3; Plut., Mor. 370b; Delph. Orac. 487, 13 [II 198 W.]; Cat. Cod. Astr. VII 166, 13; VIII 3, 186, 1; Herm. Wr. 414, 9 Sc.; Philo, Mos. 1, 110; 2, 16; Jos., Bell. 1, 377; 4, 361; TestJud 23:3; SibOr 2, 23; 8, 175.—Para uma enumeração de <span class=\"greek\">περιστάσεις</span> [crises, aflições], veja Ptolem., Apotel. 2, 1, 4 <span class=\"greek\">πολέμων</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">λιμῶν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">λοιμῶν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">σεισμῶν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">κατακλυσμῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τοιούτων</span>; sobre <span class=\"greek\">περίστασις</span>, veja Danker, Benefactor p. 363–66, e 390, n. 216 quanto à bibliografia).—PGarnsly, Famine and Food Supply in the Graeco-Roman World ’88.—B. 332. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λινοκαλάμη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λινοκαλάμη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">λίνον</span>, <span class=\"greek\">καλάμη</span>; escólio a Pla., Ep. 13 p. 363a; frequente em papiros desde o século III a.C.) caule de linho 1 Cl 12:3 (Josh 2:6; o singular tem valor coletivo).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίνον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λίνον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Homero e outros; pap, LXX; PsSol 8:5; Jos., Bell. 5, 275, Ant. 5, 9) empregado tanto para a planta do linho quanto para produtos feitos de suas fibras. Neste último sentido, na literatura aqui considerada.</p><p class=\"entry-text\">① pavio de lâmpada <span class=\"greek\">λ</span>. <span class=\"greek\">τυφόμενον</span> um pavio que fumega <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:20</a> (cf. Is 42:3).—Veja também <span class=\"greek\">κάλαμος</span> 1.</p><p class=\"entry-text\">② roupa de linho (desde Ésquilo, Suppl. 120; 132; IG IV2/1, 118, 71 [século III a.C.]; POxy 1281, 6 [21 d.C.]; PTebt 314, 16; 406, 18 <span class=\"greek\">λίνα</span> <span class=\"greek\">λευκά</span>; PGM 13, 313 <span class=\"greek\">στόλισον</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">λίνῳ</span> <span class=\"greek\">καθαρῷ</span>; cf. 650) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:6</a>.</p><p class=\"entry-text\">③ rede de pesca (Il. 5, 487; Antig. Car. 27; Philo, Agr. 24, Poster. Cai. 116) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:18</a> variante textual (em lugar de <span class=\"greek\">δίκτυα</span>) GPt 14:60.—B. 401. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λίνος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λίνος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Tat. 41, 1; Diog. L. 1, 3f; Biogr. p. 78; Sb 1283; 3169; 3625 selo de oleiro <span class=\"greek\">Λίνου</span>) Lino, cristão desconhecido por outras fontes, segundo a tradição (por exemplo Iren. 3, 3, 3 [Harv. II 10, 2]) o primeiro bispo de Roma, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:21</a>.—LGPN I.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λινοῦς, ῆ, οῦν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λινοῦς</span>, <span class=\"greek\">ῆ</span>, <span class=\"greek\">οῦν</span> (Hdt., Aristoph. e outros; ins, pap, LXX; Jos., Ant. 20, 216) (feito de) linho <span class=\"greek\">κερβικάριον</span> <span class=\"greek\">λ</span>. uma almofada de linho Hv 3, 1, 4a. <span class=\"greek\">λ</span>. <span class=\"greek\">χιτών</span> (Paus. 9, 39, 8; Philostrat., Ep. 60; SIG 736, 17 [92 a.C.]; POxy 285, 11 [c. 50 d.C.]; BGU 816, 19; Lev 6:3; 16:4) roupa de linho, túnica de linho Hs 9, 2, 4; 9, 11, 7. <span class=\"greek\">λέντιον</span> <span class=\"greek\">λινοῦν</span> <span class=\"greek\">καρπάσινον</span> um pano de linho fino v 3, 1, 4b.—DELG s.v. <span class=\"greek\">λίνον</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπαίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λιπαίνω</span> 1º aoristo <span class=\"greek\">ἐλίπανα</span>, imperativo <span class=\"greek\">λιπανάτω</span>. Na voz passiva: futuro, 3ª pessoa do singular <span class=\"greek\">λιπανθήσεται</span> Is 34:7 Theod.; aoristo, 3ª pessoa do singular <span class=\"greek\">ἐλιπάνθη</span> LXX. ungir <span class=\"greek\">τὶ</span>, algo (Philo Mech. 61, 37; Philostrat., Imag. 1, 18 p. 320, 18; PGM 36, 212) 1 Cl 56:5 (Ps 140:5).—DELG s.v. <span class=\"greek\">λίπα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπαρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λιπαρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (Homero e outros; pap, LXX) significado original «oleoso, gorduroso», depois, referente ao que é brilhante ou resplandecente, com a ideia de luxo, brilho, custo elevado e riqueza (Jos., C. Ap. 2, 229; SibOr 7, 18) como substantivo, <span class=\"greek\">τὰ</span> <span class=\"greek\">λιπαρά</span> (com <span class=\"greek\">τὰ</span> <span class=\"greek\">λαμπρά</span>; cf. SEG VIII, 550, 10 [século I a.C.]) luxo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:14</a>. Em linguagem figurada (Jos., Ant. 4, 107 <span class=\"greek\">δέησις</span> <span class=\"greek\">λ</span>.; 8, 2 <span class=\"greek\">γῆρας</span> <span class=\"greek\">λ</span>.; semelhantemente, Cat. Cod. Astr. XII 176, 20 <span class=\"greek\">λ</span>.<span class=\"greek\">γ</span>.) <span class=\"greek\">εἰρήνη</span> paz abundante e fecunda 1 Cl 2:2.—DELG s.v. <span class=\"greek\">λίπα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιποτακτέω</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λιποτακτέω</span> veja <span class=\"greek\">λειποτακτέω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιτανεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λιτανεύω</span> futuro, 3ª pessoa do plural <span class=\"greek\">λιτανεύσουσιν</span> (Ps 44:13); 1º aoristo <span class=\"greek\">ἐλιτάνευσα</span> (Homero e outros; Ps 44:13) fazer uma súplica, orar a, rogar <span class=\"greek\">Ἅννα</span> <span class=\"greek\">ἐλιτάνευσα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">δεσπότην</span> GJs 2:4; <span class=\"greek\">τινὰ</span> <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> a alguém em favor de outra pessoa <span class=\"greek\">τὸν</span> <span class=\"greek\">Χριστὸν</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἐμοῦ</span> IRo 4:2 (a respeito da oração dirigida a uma divindade: Strabo 15, 1, 60; Dionys. Hal. 4, 76; Theosophien 39; 2 Macc 14:15; EpArist 227).—DELG s.v. <span class=\"greek\">λίσσομαι</span>. M-M. s.v.-<span class=\"greek\">εία</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0219-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίτρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λίτρα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (cf. o latim libra; Polyb. 22, 26, 19; Diod S 14, 116, 7; Plut., Tib. et C. Gracch. 825 [2, 3]; Jos., Ant. 14, 106; TestJud 3:3; TestSol 21:1 Q; SIG 890: 13, 23, 24 [251 a.d.]; 954: 7, 11, 13f al.; OGI 521, 4; POxy 1454, 5; 1513, 7; 1543, 6) uma libra (romana), de 327.45 gramas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:3</a>; 19:39 (essa quantidade sugeriria um sepultamento régio?).—DELG. M-M.</p></section></article>"};
